'use strict';

// Source: js/profile-store.js
const PROFILE_DB_NAME = 'gitaverse-profiles';
const PROFILE_DB_VERSION = 1;
const PROFILE_STORE = 'profiles';
const SETTINGS_STORE = 'settings';

function requestResult(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('The profile database could not be opened.'));
  });
}

function transactionDone(transaction) {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = resolve;
    transaction.onerror = () => reject(transaction.error || new Error('The profile change could not be saved.'));
    transaction.onabort = () => reject(transaction.error || new Error('The profile change was cancelled.'));
  });
}

function openProfileDatabase() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(PROFILE_DB_NAME, PROFILE_DB_VERSION);
    request.onupgradeneeded = () => {
      const database = request.result;
      if (!database.objectStoreNames.contains(PROFILE_STORE)) {
        database.createObjectStore(PROFILE_STORE, { keyPath: 'pid', autoIncrement: true });
      }
      if (!database.objectStoreNames.contains(SETTINGS_STORE)) {
        database.createObjectStore(SETTINGS_STORE, { keyPath: 'key' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('Local profile storage is unavailable.'));
  });
}

function randomAnalyticsId() {
  if (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function') return globalThis.crypto.randomUUID();
  const bytes = new Uint8Array(16);
  globalThis.crypto.getRandomValues(bytes);
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
}

class ProfileStore {
  constructor() {
    this.database = null;
  }

  async open() {
    if (!this.database) this.database = await openProfileDatabase();
    return this;
  }

  async list() {
    await this.open();
    const transaction = this.database.transaction(PROFILE_STORE, 'readonly');
    const profiles = await requestResult(transaction.objectStore(PROFILE_STORE).getAll());
    return profiles.sort((left, right) => left.pid - right.pid);
  }

  async get(pid) {
    await this.open();
    if (!Number.isInteger(Number(pid))) return null;
    const transaction = this.database.transaction(PROFILE_STORE, 'readonly');
    return (await requestResult(transaction.objectStore(PROFILE_STORE).get(Number(pid)))) || null;
  }

  async save(input) {
    await this.open();
    const name = String(input.name || '').trim();
    if (!name) throw new Error('Enter a profile name.');
    const now = new Date().toISOString();
    const existing = input.pid ? await this.get(input.pid) : null;
    const profile = {
      ...(existing || {}),
      name,
      dob: input.dob,
      gender: input.gender || '',
      language: input.language === 'kn' ? 'kn' : 'en',
      photo: input.photo || '',
      analyticsConsent: Boolean(input.analyticsConsent),
      analyticsProfileId: existing?.analyticsProfileId || randomAnalyticsId(),
      createdAt: existing?.createdAt || now,
      updatedAt: now
    };
    if (existing) profile.pid = existing.pid;
    const transaction = this.database.transaction(PROFILE_STORE, 'readwrite');
    const request = transaction.objectStore(PROFILE_STORE).put(profile);
    const pid = await requestResult(request);
    await transactionDone(transaction);
    return this.get(pid);
  }

  async remove(pid) {
    await this.open();
    const transaction = this.database.transaction([PROFILE_STORE, SETTINGS_STORE], 'readwrite');
    transaction.objectStore(PROFILE_STORE).delete(Number(pid));
    const settings = transaction.objectStore(SETTINGS_STORE);
    const defaultPid = await requestResult(settings.get('defaultPid'));
    if (defaultPid && Number(defaultPid.value) === Number(pid)) settings.delete('defaultPid');
    await transactionDone(transaction);
  }

  async defaultPid() {
    await this.open();
    const transaction = this.database.transaction(SETTINGS_STORE, 'readonly');
    const setting = await requestResult(transaction.objectStore(SETTINGS_STORE).get('defaultPid'));
    return setting ? Number(setting.value) : null;
  }

  async setDefaultPid(pid) {
    await this.open();
    const transaction = this.database.transaction(SETTINGS_STORE, 'readwrite');
    const store = transaction.objectStore(SETTINGS_STORE);
    if (pid == null) store.delete('defaultPid');
    else store.put({ key: 'defaultPid', value: Number(pid) });
    await transactionDone(transaction);
  }
}

async function resizeProfilePhoto(file) {
  if (!file) return '';
  if (!file.type.startsWith('image/')) throw new Error('Choose an image file for the profile photo.');
  const source = await new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(new Error('The selected photo could not be read.'));
    reader.readAsDataURL(file);
  });
  const image = await new Promise((resolve, reject) => {
    const element = new Image();
    element.onload = () => resolve(element);
    element.onerror = () => reject(new Error('The selected photo is not a supported image.'));
    element.src = source;
  });
  const size = 256;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const context = canvas.getContext('2d');
  const scale = Math.max(size / image.width, size / image.height);
  const width = image.width * scale;
  const height = image.height * scale;
  context.drawImage(image, (size - width) / 2, (size - height) / 2, width, height);
  return canvas.toDataURL('image/jpeg', .82);
}

// Source: js/profile-ui.js
class ProfileUI {
  constructor({ store, onSelected, onCreated, onChanged }) {
    this.store = store;
    this.onSelected = onSelected;
    this.onCreated = onCreated;
    this.onChanged = onChanged;
    this.editingPid = null;
    this.photo = '';
    this.bind();
  }

  initials(profile) {
    return profile.name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join('').toUpperCase() || 'ॐ';
  }

  avatar(profile, className = 'profile-avatar') {
    if (profile.photo) {
      const image = document.createElement('img');
      image.className = className;
      image.src = profile.photo;
      image.alt = '';
      return image;
    }
    const fallback = document.createElement('span');
    fallback.className = className + ' profile-initials';
    fallback.textContent = this.initials(profile);
    return fallback;
  }

  async showSelection({ switching = false } = {}) {
    const profiles = await this.store.list();
    const defaultPid = await this.store.defaultPid();
    const list = document.getElementById('profile-list');
    list.textContent = '';
    profiles.forEach((profile) => {
      const card = document.createElement('article');
      card.className = 'profile-card';
      const select = document.createElement('button');
      select.type = 'button';
      select.className = 'profile-select';
      select.dataset.pid = profile.pid;
      select.appendChild(this.avatar(profile, 'profile-card-avatar'));
      const copy = document.createElement('span');
      copy.className = 'profile-card-copy';
      const name = document.createElement('strong');
      name.textContent = profile.name;
      const language = document.createElement('small');
      language.textContent = profile.language === 'kn' ? 'ಕನ್ನಡ' : 'English';
      copy.append(name, language);
      select.appendChild(copy);
      if (profile.pid === defaultPid) {
        const badge = document.createElement('span');
        badge.className = 'default-badge';
        badge.textContent = 'Default';
        select.appendChild(badge);
      }
      const actions = document.createElement('div');
      actions.className = 'profile-card-actions';
      actions.innerHTML = `<button type="button" data-profile-action="edit" data-pid="${profile.pid}">Edit</button><button type="button" data-profile-action="default" data-pid="${profile.pid}">${profile.pid === defaultPid ? 'Unset default' : 'Make default'}</button><button type="button" data-profile-action="delete" data-pid="${profile.pid}">Delete</button>`;
      card.append(select, actions);
      list.appendChild(card);
    });
    document.getElementById('profile-selection-title').textContent = switching ? 'Switch profile' : 'Who is using Gitaverse?';
    document.getElementById('profile-selection-back').hidden = !switching;
  }

  async showForm(profile = null) {
    this.editingPid = profile?.pid || null;
    this.photo = profile?.photo || '';
    document.getElementById('profile-form-title').textContent = profile ? 'Edit profile' : 'Create your profile';
    document.getElementById('profile-form-intro').textContent = profile
      ? 'Keep this profile’s local preferences up to date.'
      : 'Profiles keep each person’s language and experience separate on this device.';
    document.getElementById('profile-name').value = profile?.name || '';
    document.getElementById('profile-dob').value = profile?.dob || '';
    document.getElementById('profile-gender').value = profile?.gender || '';
    document.getElementById('profile-language').value = profile?.language || 'en';
    document.getElementById('profile-default').checked = profile ? (await this.store.defaultPid()) === profile.pid : true;
    document.getElementById('profile-form-cancel').hidden = !profile;
    document.getElementById('profile-form-error').textContent = '';
    this.renderPhotoPreview(profile);
  }

  renderPhotoPreview(profile = null) {
    const preview = document.getElementById('profile-photo-preview');
    preview.textContent = '';
    preview.appendChild(this.avatar({ name: document.getElementById('profile-name').value || profile?.name || '', photo: this.photo }, 'profile-photo-avatar'));
    document.getElementById('profile-photo-remove').hidden = !this.photo;
  }

  async renderPills(profile) {
    document.querySelectorAll('[data-profile-pill]').forEach((button) => {
      button.textContent = '';
      button.appendChild(this.avatar(profile, 'profile-pill-avatar'));
      const name = document.createElement('span');
      name.textContent = profile.name;
      button.appendChild(name);
      button.dataset.pid = profile.pid;
      button.setAttribute('aria-label', 'Profile: ' + profile.name + '. Open profile options.');
    });
  }

  bind() {
    document.getElementById('profile-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      const error = document.getElementById('profile-form-error');
      error.textContent = '';
      try {
        const dob = document.getElementById('profile-dob').value;
        if (!dob || new Date(dob + 'T00:00:00') > new Date()) throw new Error('Enter a valid date of birth.');
        const profile = await this.store.save({
          pid: this.editingPid,
          name: document.getElementById('profile-name').value,
          dob,
          gender: document.getElementById('profile-gender').value,
          language: document.getElementById('profile-language').value,
          photo: this.photo,
          analyticsConsent: true
        });
        if (document.getElementById('profile-default').checked) await this.store.setDefaultPid(profile.pid);
        else if ((await this.store.defaultPid()) === profile.pid) await this.store.setDefaultPid(null);
        if (this.editingPid) await this.onChanged(profile);
        else await this.onCreated(profile);
      } catch (failure) {
        error.textContent = failure.message || 'The profile could not be saved.';
      }
    });
    document.getElementById('profile-name').addEventListener('input', () => this.renderPhotoPreview());
    document.getElementById('profile-photo').addEventListener('change', async (event) => {
      const error = document.getElementById('profile-form-error');
      try {
        this.photo = await resizeProfilePhoto(event.target.files?.[0]);
        this.renderPhotoPreview();
      } catch (failure) { error.textContent = failure.message; }
    });
    document.getElementById('profile-photo-remove').addEventListener('click', () => {
      this.photo = '';
      document.getElementById('profile-photo').value = '';
      this.renderPhotoPreview();
    });
    document.getElementById('profile-list').addEventListener('click', async (event) => {
      const select = event.target.closest('.profile-select');
      if (select) return this.onSelected(await this.store.get(select.dataset.pid));
      const action = event.target.closest('[data-profile-action]');
      if (!action) return;
      const profile = await this.store.get(action.dataset.pid);
      if (action.dataset.profileAction === 'edit') return this.onChanged(profile, { edit: true });
      if (action.dataset.profileAction === 'default') {
        const current = await this.store.defaultPid();
        await this.store.setDefaultPid(current === profile.pid ? null : profile.pid);
        return this.showSelection({ switching: true });
      }
      if (action.dataset.profileAction === 'delete' && window.confirm('Delete the profile “' + profile.name + '” from this device?')) {
        await this.store.remove(profile.pid);
        const remaining = await this.store.list();
        if (!remaining.length) return this.onChanged(null, { setup: true });
        return this.onChanged(null, { deletedPid: profile.pid, remaining });
      }
    });
  }
}

// Source: js/master-data.js
const MASTER_URL = 'data/master.csv';

const EXPECTED_HEADERS = [
  'cid', 'snum', 'sid', 'shloka_sa', 'cname_sa', 'meaning_sa',
  'word_by_word_meaning_sa', 'shloka_transliteration_en', 'cname_en',
  'meaning_en', 'word_by_word_meaning_en', 'shloka_transliteration_kn',
  'cname_kn', 'meaning_kn', 'word_by_word_meaning_kn',
  'audio_gita_700', 'audio_gita_yoga', 'icon_gita_700'
];

function logicalRecords(text) {
  const physical = String(text || '').replace(/^\uFEFF/, '').replace(/\r\n?/g, '\n').split('\n');
  const records = [];
  let buffer = '';
  let wrapped = false;
  physical.forEach((line) => {
    if (!buffer) {
      wrapped = line.charAt(0) === '"';
      buffer = line;
    } else {
      buffer += '\n' + line;
    }
    if (!wrapped || /"\s*$/.test(line)) {
      records.push(buffer);
      buffer = '';
      wrapped = false;
    }
  });
  if (buffer.trim()) records.push(buffer);
  return records.filter((record) => record.trim());
}

function unwrap(record) {
  const trimmed = record.trim();
  if (trimmed.charAt(0) === '"' && trimmed.charAt(trimmed.length - 1) === '"') {
    return trimmed.slice(1, -1).replace(/""/g, '"');
  }
  return record;
}

function decodeValue(value) {
  return String(value || '').replace(/\\n/g, '\n');
}

function encodeValue(value) {
  const encoded = String(value == null ? '' : value).replace(/\r\n?/g, '\n').replace(/\n/g, '\\n');
  if (encoded.includes('#')) throw new Error('The # character is not allowed in master data.');
  return encoded;
}

function parseMaster(text) {
  const records = logicalRecords(text);
  if (records.length < 2) throw new Error('The master data contains no shloka records.');
  const headers = unwrap(records.shift()).split('#').map((header) => header.trim());
  if (headers.join('#') !== EXPECTED_HEADERS.join('#')) {
    throw new Error('The selected file header does not match the required ' + EXPECTED_HEADERS.length + '-column master.csv format.');
  }

  const rows = [];
  const seen = new Set();
  const invalid = [];
  records.forEach((record, recordIndex) => {
    const values = unwrap(record).split('#');
    if (values.length !== headers.length) {
      invalid.push(recordIndex + 2);
      return;
    }
    const row = {};
    headers.forEach((header, index) => { row[header] = decodeValue(values[index]); });
    if (!row.sid || row.sid !== row.cid + '.' + row.snum) {
      throw new Error('Invalid master data record ' + (recordIndex + 2) + ': sid must equal cid.snum.');
    }
    if (seen.has(row.sid)) throw new Error('Duplicate sid in master data: ' + row.sid + '.');
    seen.add(row.sid);
    rows.push(row);
  });
  if (invalid.length) {
    throw new Error('Invalid master data records: ' + invalid.slice(0, 8).join(', ') + '. Each record must contain exactly ' + EXPECTED_HEADERS.length + ' fields.');
  }
  if (!rows.length) throw new Error('The selected file contains no usable records.');
  return { headers, rows };
}

function serializeMaster(dataset) {
  const headers = dataset.headers || EXPECTED_HEADERS;
  if (headers.join('#') !== EXPECTED_HEADERS.join('#')) throw new Error('Cannot export an unsupported master schema.');
  const lines = [headers.join('#')];
  dataset.rows.forEach((row) => {
    lines.push(headers.map((header) => encodeValue(row[header])).join('#'));
  });
  return lines.join('\n') + '\n';
}

async function loadMaster(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error('Could not load ' + MASTER_URL + ' (HTTP ' + response.status + ').');
  return parseMaster(await response.text());
}

async function readMasterFile(file) {
  if (!file) throw new Error('No master file was selected.');
  return parseMaster(await file.text());
}

function value(row, names) {
  for (const name of names) {
    if (Object.prototype.hasOwnProperty.call(row, name)) return row[name] || '';
  }
  return '';
}

function languageField(stem, language) {
  if (stem === 'transliteration') return 'shloka_transliteration_' + language;
  return stem + '_' + language;
}

// Source: js/audio-player.js
class AudioPlayer {
  constructor({ audio, playButton, playIcon, pauseIcon, seek, time }) {
    this.audio = audio;
    this.playButton = playButton;
    this.playIcon = playIcon;
    this.pauseIcon = pauseIcon;
    this.seek = seek;
    this.time = time;
    this.bind();
  }

  bind() {
    this.playButton.addEventListener('click', () => this.toggle());
    this.audio.addEventListener('play', () => this.updatePlayState());
    this.audio.addEventListener('pause', () => this.updatePlayState());
    this.audio.addEventListener('ended', () => this.updatePlayState());
    this.audio.addEventListener('loadedmetadata', () => {
      this.seek.max = Number.isFinite(this.audio.duration) ? String(this.audio.duration) : '0';
      this.seek.disabled = !Number.isFinite(this.audio.duration) || this.audio.duration <= 0;
      this.time.textContent = '00:00 / ' + this.formatTime(this.audio.duration);
    });
    this.audio.addEventListener('timeupdate', () => {
      this.seek.value = String(this.audio.currentTime || 0);
      this.time.textContent = this.formatTime(this.audio.currentTime) + ' / ' + this.formatTime(this.audio.duration);
    });
    this.seek.addEventListener('input', (event) => {
      if (Number.isFinite(this.audio.duration)) this.audio.currentTime = Number(event.target.value);
    });
    this.audio.addEventListener('error', () => {
      this.time.textContent = 'Audio unavailable';
      this.playButton.disabled = true;
      this.seek.disabled = true;
      this.updatePlayState();
    });
  }

  setSource(source) {
    this.stop();
    this.audio.removeAttribute('src');
    if (source) this.audio.src = source;
    this.playButton.disabled = !source;
    this.seek.disabled = !source;
    this.seek.max = '0';
    this.seek.value = '0';
    this.time.textContent = source ? '00:00 / 00:00' : 'No audio';
  }

  toggle() {
    if (!this.audio.getAttribute('src')) return;
    if (this.audio.paused) this.audio.play().catch(() => this.updatePlayState());
    else this.audio.pause();
  }

  stop() {
    this.audio.pause();
    this.audio.currentTime = 0;
    this.seek.value = '0';
    this.updatePlayState();
  }

  updatePlayState() {
    const playing = !this.audio.paused && !this.audio.ended;
    this.playIcon.toggleAttribute('hidden', playing);
    this.pauseIcon.toggleAttribute('hidden', !playing);
    this.playButton.setAttribute('aria-label', playing ? 'Pause audio' : 'Play audio');
    this.playButton.title = (playing ? 'Pause audio' : 'Play audio') + ' (P or Space)';
  }

  formatTime(seconds) {
    if (!Number.isFinite(seconds)) return '00:00';
    const minutes = Math.floor(seconds / 60);
    const remainder = Math.floor(seconds % 60);
    return String(minutes).padStart(2, '0') + ':' + String(remainder).padStart(2, '0');
  }
}

// Source: js/renderers/gita-700.js
const PANELS = [
  { role: 'shloka', panelClass: 'shloka', max: [42, 36], min: 10 },
  { role: 'meaning', panelClass: 'meaning', max: [31, 27], min: 10 },
  { role: 'transliteration', panelClass: 'transliteration', max: [30, 27], min: 10 },
  { role: 'word', panelClass: 'word', max: [22, 19], min: 9 }
];

function createGita700Renderer() {
  let root;
  let editing = false;

  function fieldFor(role, language) {
    if (role === 'shloka') return 'shloka_sa';
    if (role === 'word') return languageField('word_by_word_meaning', language);
    return languageField(role, language);
  }

  function mount(container) {
    root = container;
    root.innerHTML = '<div class="gita-700-panels">' + PANELS.map((panel) =>
      '<article class="gita-700-panel gita-700-panel-' + panel.panelClass + '">' +
        '<div class="gita-700-panel-content" data-panel="' + panel.role + '">' +
          '<div class="gita-700-text" data-role="' + panel.role + '"></div>' +
        '</div>' +
      '</article>'
    ).join('') + '</div>';
  }

  function render(row, language) {
    PANELS.forEach((panel) => {
      const field = fieldFor(panel.role, language);
      const element = root.querySelector('[data-role="' + panel.role + '"]');
      const text = value(row, [field]);
      element.dataset.field = field;
      element.textContent = text || '—';
      element.classList.toggle('empty', !text);
      if (editing) makeEditable(element);
    });
    if (!editing) requestAnimationFrame(fitText);
  }

  function makeEditable(element) {
    element.contentEditable = 'true';
    element.spellcheck = false;
    element.dataset.editField = element.dataset.field;
    element.classList.remove('empty');
    if (element.textContent === '—') element.textContent = '';
  }

  function setEditing(enabled) {
    editing = enabled;
    root.querySelectorAll('[data-role]').forEach((element) => {
      if (enabled) makeEditable(element);
      else {
        element.contentEditable = 'false';
        delete element.dataset.editField;
      }
    });
    if (!enabled) requestAnimationFrame(fitText);
  }

  function editableElements() {
    return Array.from(root.querySelectorAll('[data-edit-field]'));
  }

  function fitElement(panel, text, maxSize, minSize) {
    if (!panel || !text || !panel.clientHeight) return;
    let low = minSize;
    let high = maxSize;
    let best = minSize;
    while (low <= high) {
      const middle = Math.floor((low + high) / 2);
      text.style.fontSize = middle + 'px';
      if (text.scrollHeight <= panel.clientHeight - 4 && text.scrollWidth <= panel.clientWidth - 4) {
        best = middle;
        low = middle + 1;
      } else {
        high = middle - 1;
      }
    }
    text.style.fontSize = best + 'px';
  }

  function fitText() {
    if (editing || !root) return;
    const mobile = matchMedia('(max-width: 760px)').matches;
    PANELS.forEach((panel) => {
      fitElement(
        root.querySelector('[data-panel="' + panel.role + '"]'),
        root.querySelector('[data-role="' + panel.role + '"]'),
        panel.max[mobile ? 1 : 0],
        panel.min
      );
    });
  }

  return {
    id: 'gita-700',
    audioField: 'audio_gita_700',
    mount,
    render,
    setEditing,
    editableElements,
    fitText,
    destroy() { if (root) root.textContent = ''; root = null; }
  };
}

// Source: js/renderers/registry.js
const experiences = {
  'gita-700': {
    available: true,
    label: 'Gita 700',
    load: async () => createGita700Renderer()
  },
  'gita-yoga': { available: false, label: 'Gita Yoga' },
  'gita-sara': { available: false, label: 'Gita Sara' }
};

function getExperience(id) {
  return experiences[id] || null;
}

function availableExperiences() {
  return Object.entries(experiences).filter(([, experience]) => experience.available);
}

